import {createRequire} from 'node:module';
import {compileFunction} from 'node:vm';
import assert from 'node:assert/strict';
import {readFile, writeFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
// Execute pinned copied bundle fragments without invoking the live plugin.
function compile(...parameters) {
  const body = parameters.pop();
  return compileFunction(body, parameters);
}
const [source, output] = process.argv.slice(2);
const require = createRequire(new URL('../../workflow-timers/package.json', import.meta.url));
const text = (await readFile(source, 'utf8')).replaceAll('from"zod"', 'from '+JSON.stringify(require.resolve('zod'))).replaceAll('from"@get-bb/plugin-sdk"', 'from '+JSON.stringify(require.resolve('@get-bb/plugin-sdk')));
await writeFile(output, text + '\nexport {Ws, Ge, Os, Lp, fr, kp, bv, Mo};\n');
const {Ws, Ge, Os, Lp, fr, kp, bv, Mo} = await import(pathToFileURL(output));
const stock = {selection:null, outputSchema:null, title:null, phase:null};
assert.equal(Ge(stock).title, null);
const historical = {...stock, sessionOptions:{turbo:true}, sessionOptionLabels:['Turbo']};
assert.deepEqual(Ge(historical).sessionOptionLabels, ['Turbo']);
assert.deepEqual(Ws({sessionOptions:{turbo:false}}).sessionOptions, {turbo:false});
assert.throws(() => Ws({sessionOptions:{turbo:3}}));
assert.throws(() => Ws({unknown:true}));
const input = {version:2, previousCacheKey:null, prompt:'Synthetic review', selection:{providerId:'example',model:'example',reasoningLevel:'high',permissionMode:'auto'}, outputSchema:null, executionSemantics:{workerPromptVersion:'v1',resultProtocolVersion:'v1',maxRepairAttempts:1}};
const base = Os(input);
assert.notEqual(base, Os({...input, selection:{...input.selection,sessionOptions:{turbo:true}}}));
assert.notEqual(Os({...input, selection:{...input.selection,sessionOptions:{turbo:false}}}), Os({...input, selection:{...input.selection,sessionOptions:{turbo:true}}}));
assert.equal(Os({...input,selection:{...input.selection,sessionOptions:{a:true,b:'x'}}}),Os({...input,selection:{...input.selection,sessionOptions:{b:'x',a:true}}}));
const call = {id:'call-example',callIndex:0,prompt:'Synthetic review',options:Ge(historical),execution:{provider:'example',model:'example',reasoningLevel:'high'},source:'live'};
assert.deepEqual(Lp(call).sessionOptionLabels,['Turbo']);
assert.deepEqual(Lp({...call,options:Ge(stock)}).sessionOptionLabels,[]);
console.log('PASS stored stock/historical schemas, strict parser, cache isolation, view labels');

const resolverStart=text.indexOf('function bbResolveSessionOptions(');
const resolverEnd=text.indexOf('async function ur(u,p,j){',resolverStart);
const resolve=compile(`return (${text.slice(resolverStart,resolverEnd).trim()});`)();
const model = {sessionOptions:[{id:'turbo',label:'Turbo',type:'boolean',value:false},{id:'mode',label:'Mode',type:'select',values:[{id:'fast',label:'Fast'}]},{id:'locked',label:'Locked',type:'boolean',fixed:true,value:true}]};
assert.deepEqual(resolve(model,{turbo:false,mode:'fast'}),{selections:{turbo:false,mode:'fast'},labels:['Turbo off','Mode: Fast']});
assert.deepEqual(resolve(model,null),{selections:undefined,labels:[]});
for (const options of [{unknown:true},{turbo:'true'},{mode:true},{mode:'missing'},{locked:false}]) assert.throws(()=>resolve(model,options));
assert.deepEqual(resolve(model,{locked:true}).labels,['Locked']);
const validation = text.slice(text.indexOf('async function ur(u,p,j){'),text.indexOf('}F(ur,"validateSelection")')+1);
const validate = compile('x','C','fr','kp','bbResolveSessionOptions',`return (${validation});`)({sdk:{providers:{list:async()=>[{id:'example',available:true,capabilities:{permissionModes:['auto']}}],models:async()=>({models:[{...model,id:'example',model:'example',supportedReasoningEfforts:[{reasoningEffort:'high'}]}],selectedOnlyModels:[],modelLoadError:null})}}},()=>{},fr,kp,resolve);
const origin={originProvider:'example',originModel:'example',originReasoningLevel:'high',originPermissionMode:'auto'};
const selection=await validate(origin,Ws({sessionOptions:{turbo:true}}));
assert.deepEqual(selection.sessionOptions,{turbo:true});
assert.deepEqual(selection.sessionOptionLabels,['Turbo']);
await assert.rejects(validate(origin,Ws({sessionOptions:{locked:false}})));
const spawnStart=text.indexOf('x.sdk.threads.spawn({')+'x.sdk.threads.spawn('.length;
const spawnEnd=text.indexOf(');if(GF',spawnStart);
const spawn=compile('u','g','j','_','p','Q','d8',`return (${text.slice(spawnStart,spawnEnd)});`)(origin,{id:'call-example'},'Review',Ws({sessionOptions:{turbo:true}}),0,selection,()=> 'Synthetic prompt');
assert.deepEqual(spawn.sessionOptions,{turbo:true});
assert.equal(spawn.providerId,'example');
const guardStart=text.indexOf('function i(n,s){let o=s===null?t.inspectLatestForThread(n):t.inspect(s);');
assert.ok(guardStart>0);
const guardEnd=text.indexOf('}F(i,"workflowForThread")',guardStart)+1;
const guard=compile('t',`return (${text.slice(guardStart,guardEnd)});`)({inspect:()=>({originThreadId:'origin-example'}),inspectLatestForThread:()=>null});
assert.equal(guard('origin-example','run-example').originThreadId,'origin-example');
assert.throws(()=>guard('another-origin','run-example'),/not available in this thread/);
assert.equal(guard('origin-example',null),null);
const complete={...call,status:'succeeded',childThreadId:null,providerRetryAttempts:0,repairAttempts:0,error:null,createdAt:1,startedAt:1,finishedAt:2};
assert.deepEqual(bv.parse(Lp(complete)).sessionOptionLabels,['Turbo']);
const app=await readFile(new URL('app.js',pathToFileURL(source)),'utf8');
const metadata=app.match(/metadata:(\[i\.provider,\$n\(i\.model\),i\.reasoningLevel[^\]]*\])/)[1];
assert.deepEqual(compile('i','$n',`return ${metadata}`)({provider:'example',model:'example',reasoningLevel:'high',sessionOptionLabels:['Turbo']},x=>x),['example','example','high','Turbo']);
console.log('PASS model validation, fixed/select/boolean semantics, effective spawn, ownership guard, RPC schema, progress metadata');

const workflow='export const meta = {name:"synthetic-review",description:"Synthetic option check"}; return await agent("Review", {provider:"example",model:"example",reasoningLevel:"high",sessionOptions:{turbo:true}});';
const valid=await Mo(workflow,'environment-example',{listProviders:async()=>[{id:'example',available:true}],loadModels:async()=>({models:[{id:'example',model:'example',supportedReasoningEfforts:[{reasoningEffort:'high'}]}],modelLoadError:null})});
assert.equal(valid.valid,true);
assert.equal(valid.literalSelections.length,1);
console.log('PASS workflow source validation with explicit selection and session options');
